insert into public.board_exam_questions (board, contest_name, career_name, exam_year, exam_date, exam_type, item_number, subject, support_text, stem, options, official_answer, needs_visual, legal_review_required, law_version_checked_at, legal_basis, state, career_category, source_url, answer_key_url, review_note) values
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',1,'Direito Penal',null,'Guilherme, 38 anos de idade, em 31 de maio de 2024, na cidade de Tubarão-SC, adentrou um Supermercado Carrefour para adquirir produtos de limpeza, carnes e chocolates. Ele, percebendo os valores dos produtos, sem violência ou grave ameaça à pessoa, subtraiu, para si, uma caixa de chocolate, avaliada em R$ 30 (trinta) reais. Ao sair do supermercado, Guilherme é preso em flagrante delito pelos seguranças do estabelecimento. Com base nos fatos narrados, marque a afirmativa correta.','{"A": "Não é aplicável, ao caso, o princípio da insignificância, tendo em vista ter havido dano relevante ao bem jurídico patrimônio do supermercado.", "B": "É aplicável, ao caso, o princípio da insignificância, que exclui a tipicidade em sua dimensão material.", "C": "É aplicável, ao caso, o princípio da insignificância, que exclui a tipicidade em sua dimensão formal.", "D": "Não é aplicável, ao caso, o princípio da insignificância, tendo em vista o valor da caixa de chocolates.", "E": "É aplicável, ao caso, o princípio da insignificância, que exclui a antijuridicidade da conduta praticada."}'::jsonb,'B',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Busca de alterações 2025-2026 no CP não encontrou mudança nos dispositivos cobrados; texto integral não relido.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',2,'Direito Penal',null,'Simone, 49 anos de idade, doutora em Direito Civil e professora universitária, realiza um sonho de criança ao conhecer a linda cidade de Florianópolis-SC. Durante a sua estada, entusiasmada com a riqueza cultural da cidade e o reencontro com a sua amiga de infância, Natalia, 47 anos de idade, Simone aceita pequena quantidade de pó branco que lhe é oferecida por Paulo, guia turístico. Simone, acreditando tratarse de brincadeira com farinha, recebe o pó branco e o guarda em sua mochila de praia. Passados alguns minutos, Simone é surpreendida por policiais civis que a imputam a prática de crime de tráfico de drogas. Com base nos fatos narrados, marque a afirmativa correta.','{"A": "Em tese, Simone teria incidido em erro de tipo que, nos termos do artigo 21 do Código Penal, se inescusável afastaria o dolo e a culpa.", "B": "Em tese, Simone teria incidido em erro de tipo que, nos termos do artigo 20 do Código Penal, se escusável geraria a redução da pena de um sexto a um terço.", "C": "Em tese, Simone teria incidido em erro de proibição que, nos termos do artigo 21 do Código Penal, se escusável excluiria o dolo, mas permitiria a punição na modalidade culposa.", "D": "Em tese, Simone teria incidido em erro de proibição que, nos termos do artigo 21 do Código Penal, se escusável geraria a exclusão da antijuridicidade ou ilicitude.", "E": "Em tese, Simone teria incidido em erro de tipo que, nos termos do artigo 20 do Código Penal, se escusável afastaria o dolo e a culpa."}'::jsonb,'E',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Busca de alterações 2025-2026 no CP não encontrou mudança nos dispositivos cobrados; texto integral não relido.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',3,'Direito Penal',null,'Mário, 58 anos de idade, médico, em decorrência de cobranças de dívidas por parte de André, 42 anos de idade, decide ceifar a vida de André. Em 31 de maio de 2024, Mário, com animus necandi e portando arma de fogo com dez projéteis, dirige-se até a residência de André para concretizar seu desejo. Ao se deparar com André, Mário efetua os dez disparos de arma de fogo contra a vítima. Após efetuar os dez disparos, Mário é tomado por uma sensação divina e, de imediato, coloca André em seu carro e o leva até o hospital mais próximo. André é submetido a algumas cirurgias e sobrevive. A partir da situação apresentada, marque a afirmativa correta.','{"A": "Aplica-se, ao caso, o instituto do arrependimento posterior e Mário deverá responder criminalmente pelo crime de tentativa de homicídio.", "B": "Aplica-se, ao caso, o instituto da desistência voluntária e Mário deverá responder criminalmente pelo crime de tentativa de homicídio.", "C": "Aplica-se, ao caso, o instituto do arrependimento posterior e Mário deverá responder criminalmente pelo crime de lesão corporal.", "D": "Aplica-se, ao caso, o instituto do arrependimento eficaz e Mário deverá responder criminalmente pelo crime de lesão corporal.", "E": "Aplica-se, ao caso, o instituto da desistência voluntária e Mário deverá responder criminalmente pelo crime de lesão corporal."}'::jsonb,'D',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Busca de alterações 2025-2026 no CP não encontrou mudança nos dispositivos cobrados; texto integral não relido.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',4,'Direito Penal',null,'Em maio de 2022, Rodrigo, 62 anos de idade, casado, contador, mediante ardil, induz em erro Luciana, 61 anos de idade, divorciada, médica, e obtém, para si, vantagem ilícita em prejuízo de Luciana, gerando relevante resultado gravoso. Com base nos fatos narrados, marque a afirmativa correta.','{"A": "Rodrigo praticara o crime de estelionato com a incidência da majorante de um terço até o dobro por ter tido como vítima pessoa idosa.", "B": "Rodrigo praticara o crime de estelionato com a incidência da majorante de um terço até a metade por ter tido como vítima pessoa idosa.", "C": "Rodrigo praticara o crime de estelionato com a incidência da majorante de um sexto até a metade por ter tido como vítima pessoa idosa.", "D": "Rodrigo praticara o crime de estelionato sem a incidência da majorante de um terço até o dobro por não ter tido como vítima pessoa idosa.", "E": "Rodrigo praticara o crime de estelionato com a incidência da majorante de um terço a dois terços por ter tido como vítima pessoa idosa."}'::jsonb,'A',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Busca de alterações 2025-2026 no CP não encontrou mudança nos dispositivos cobrados; texto integral não relido.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',5,'Direito Penal',null,'João Bosco, 34 anos de idade, Delegado da Polícia Federal, é casado com Roberta, 32 anos de idade, psicóloga. O casal tem o sonho de ter filhos. Após anos de tentativas frustradas, o casal adota uma linda menina de 4 meses, a amada Maria Antonieta. No ano de 2024, Maria Antonieta, com 8 anos de idade, é vítima do crime de homicídio perpetrado por Rogério Duarte, 56 anos de idade. Rogério havia sido preso em flagrante pelo Delegado João Bosco, no ano de 2018, por envolvimento em tráfico internacional de drogas. Após a prisão, Rogério prometera se vingar do Delegado da Polícia Federal, o que se concretizara na prática de homicídio contra Maria Antonieta. Com base nos fatos narrados e no Código Penal, assinale a alternativa correta.','{"A": "Incidirá a qualificadora do homicídio praticado contra autoridade ou agente descrito nos artigos 142 e 144 da Constituição da República de 1988, integrantes do Sistema Prisional e da Força Nacional de Segurança Pública, no exercício da função ou em decorrência dela, ou contra o seu cônjuge, companheiro ou parente consanguíneo ou de qualquer natureza, até o segundo grau, em razão dessa condição.", "B": "Incidirá a qualificadora do homicídio praticado contra autoridade ou agente descrito nos artigos 142 e 144 da Constituição da República de 1988, integrantes do Sistema Prisional e da Força Nacional de Segurança Pública, no exercício da função ou em decorrência dela, ou contra o seu cônjuge, companheiro ou parente consanguíneo ou de qualquer natureza, até o quarto grau, em razão dessa condição.", "C": "Incidirá a qualificadora do homicídio praticado contra autoridade ou agente descrito nos artigos 142 e 144 da Constituição da República de 1988, integrantes do Sistema Prisional e da Força Nacional de Segurança Pública, no exercício da função ou em decorrência dela, ou contra o seu cônjuge, companheiro ou parente consanguíneo, até o segundo grau, em razão dessa condição.", "D": "Não incidirá a qualificadora do homicídio praticado contra autoridade ou agente descrito nos artigos 142 e 144 da Constituição da República de 1988, integrantes do Sistema Prisional e da Força Nacional de Segurança Pública, no exercício da função ou em decorrência dela, ou contra o seu cônjuge, companheiro ou parente consanguíneo, até o terceiro grau, em razão dessa condição.", "E": "Incidirá a qualificadora do homicídio praticado contra autoridade ou agente descrito nos artigos 142 e 144 da Constituição da República de 1988, integrantes do Sistema Prisional e da Força Nacional de Segurança Pública, no exercício da função ou em decorrência dela, ou contra o seu cônjuge, companheiro ou parente consanguíneo, até o quarto grau, em razão dessa condição, com base em uma interpretação extensiva do conceito de filho, o que é admissível no Constitucional Direito Penal."}'::jsonb,'D',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Busca de alterações 2025-2026 no CP não encontrou mudança nos dispositivos cobrados; texto integral não relido.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',6,'Direito Penal',null,'Américo, 48 anos de idade, professor efetivo no Curso de Direito da Universidade Federal de Santa Catarina (UFSC), está na fase de escrever a sua tese de doutorado na Universidade Estadual do Rio de Janeiro (UERJ). Com o objetivo de facilitar o desenvolvimento da tese, Américo e seu irmão, Marcelo, 46 anos de idade, valendo-se do acesso irrestrito de Américo na UFSC, se apropriam do computador institucional de que Américo tem a posse em razão do cargo e o levam para a residência de Américo. Quando da posse no cargo de professor efetivo na UFSC, Marcelo presenteou Américo com uma linda coleção de Direito Penal do jurista Nelson Hungria. Nesse contexto, marque a afirmativa correta.','{"A": "No caso de participação de menor importância reconhecida na decisão penal condenatória, a pena poderá ser reduzida de um sexto até a metade.", "B": "A elementar típica, funcionário público, do crime de peculato se comunica a Marcelo, com base no artigo 30 do Código Penal.", "C": "Américo, por ser funcionário público, deverá responder criminalmente pelo crime de peculato e Marcelo, por não ser funcionário público, deverá responder pelo crime de furto.", "D": "Américo e Marcelo deverão responder criminalmente pelo crime de furto, com base na teoria monista.", "E": "O artigo 29 do Código Penal, ao estabelecer que quem, de qualquer modo concorre para o crime, incide nas penas a este cominadas, na medida de sua culpabilidade, adota, como regra, a teoria pluralista no concurso de pessoas."}'::jsonb,'B',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Busca de alterações 2025-2026 no CP não encontrou mudança nos dispositivos cobrados; texto integral não relido.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',7,'Direito Penal',null,'Rafhael, 41 anos de idade, com a intenção de presentear sua esposa, Karina, 38 anos de idade, adentra a uma renomada joalheria em Florianópolis e, aproveitando-se da distração da funcionária, subtrai um colar de ouro avaliado em duzentos mil reais. Rafhael esconde o colar em sua mochila e, aparentando ser uma pessoa honesta e de trato agradável, deixa a loja conversando naturalmente com a funcionária. Quando Rafhael se encontra na esquina da joalheria, três seguranças do estabelecimento comercial que acompanhavam os fatos pelas câmeras capturam Rafhael em flagrante delito. Com base nos fatos narrados, indique a alternativa correta.','{"A": "Rafhael praticara o delito de furto consumado, com base na teoria da amotio adotada pelo Direito Penal Brasileiro.", "B": "Rafhael praticara o delito de furto consumado, com base na teoria da ablatio adotada pelo Direito Penal Brasileiro.", "C": "Rafhael praticara o delito de furto tentado, com base na teoria da amotio adotada pelo Direito Penal Brasileiro.", "D": "Rafhael praticara o delito de furto consumado, com base na teoria da contrectatio adotada pelo Direito Penal Brasileiro.", "E": "Rafhael praticara o delito de furto tentado, com base na teoria da ablatio adotada pelo Direito Penal Brasileiro."}'::jsonb,'A',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Busca de alterações 2025-2026 no CP não encontrou mudança nos dispositivos cobrados; texto integral não relido.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',8,'Direito Penal',null,'Cristina, 42 anos de idade, Delegada de Polícia no Estado de Santa Catarina, no dia 24 de dezembro de 2025, após encerrar um plantão de trabalho na Delegacia Especializada em crimes contra a dignidade sexual, dirigindo seu veículo e com o objetivo de chegar em sua residência para as festividades de natal, imprime velocidade excessiva, perde o controle em determinada curva e colide, frontalmente, com outro veículo. Em decorrência da colisão, Álvaro e Rodrigo, passageiros do outro veículo, falecem ainda no local do acidente. Nesse contexto, assinale a afirmativa correta.','{"A": "Haverá, no caso, a incidência do concurso material de crimes e se levará em consideração apenas uma das penas, se iguais, ou a mais gravosa, se diversas, aumentada, em qualquer caso, de um sexto até dois terços.", "B": "Haverá, no caso, a incidência do concurso material de crimes e as penas serão somadas, com base no critério do cúmulo material.", "C": "Haverá, no caso, a incidência do concurso formal próprio de crimes e se levará em consideração apenas uma das penas, se iguais, ou a mais gravosa, se diversas, aumentada, em qualquer caso, de um sexto até a metade.", "D": "Haverá, no caso, a incidência do concurso formal impróprio de crimes e as penas serão somadas, com base no critério da exasperação da pena.", "E": "Haverá, no caso, a incidência do crime continuado, tendo em vista tratar-se de crimes idênticos cometidos mediante uma única ação ou omissão."}'::jsonb,'C',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Busca de alterações 2025-2026 no CP não encontrou mudança nos dispositivos cobrados; texto integral não relido.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',9,'Direito Penal',null,'José Flávio, 45 anos de idade, residente em São Paulo, capital, em viagem de automóvel para a Joinville-SC, é parado em um Posto da Polícia Rodoviária Federal. Ao realizar a conferência dos documentos, o policial identifica que o certificado do automóvel estava vencido e que José Flávio não possuía habilitação para dirigir veículo automotor. Ato contínuo, o policial encara José Flávio, dá um sorriso irônico e solicita cinco mil reais para liberá-lo. José Flávio não paga o valor solicitado e tem o seu veículo apreendido. Com base no exposto, marque a opção correta.','{"A": "O policial rodoviário federal praticara o delito de corrupção passiva na modalidade tentada.", "B": "José Flávio praticara o delito de corrupção passiva.", "C": "O policial rodoviário federal praticara o delito de corrupção ativa na modalidade consumada.", "D": "O policial rodoviário federal praticara o delito de corrupção ativa na modalidade tentada.", "E": "O policial rodoviário federal praticara o delito de corrupção passiva na modalidade consumada."}'::jsonb,'E',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Busca de alterações 2025-2026 no CP não encontrou mudança nos dispositivos cobrados; texto integral não relido.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',10,'Direito Penal',null,'José Augusto, 34 anos de idade, e Flávio Henrique, 28 anos de idade, na festa de réveillon de 2024, em Blumenau-SC, mediante violência, constrangem Solange, 21 anos de idade, a ter conjunção carnal com ambos. Os atos sexuais são realizados. Com base nos fatos narrados, marque a alternativa correta.','{"A": "José Augusto e Flávio Henrique cometeram o crime de estupro de vulnerável em virtude da impossibilidade da vítima em oferecer resistência.", "B": "José Augusto e Flávio Henrique cometeram o crime de estupro com a causa de aumento de pena de um terço a metade em virtude do concurso de pessoas.", "C": "José Augusto e Flávio Henrique cometeram o crime de estupro com a causa de aumento de pena de um terço a dois terços em virtude do concurso de pessoas.", "D": "José Augusto e Flávio Henrique cometeram o crime de estupro com a causa de aumento de pena de um sexto até a metade em virtude do concurso de pessoas.", "E": "José Augusto e Flávio Henrique cometeram o crime de estupro com a causa de aumento de pena de um sexto ao dobro em virtude do concurso de pessoas."}'::jsonb,'C',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Busca de alterações 2025-2026 no CP não encontrou mudança nos dispositivos cobrados; texto integral não relido.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',11,'Direito Processual Penal',null,'O artigo 158-A, do Código de Processo Penal, conceitua cadeia de custódia como sendo o conjunto de todos os procedimentos utilizados para manter e documentar a história cronológica do vestígio coletado em locais ou em vítimas de crimes, para rastrear sua posse e manuseio a partir de seu reconhecimento até o descarte. Com base no tema cadeia de custódia e no Código de Processo Penal, marque a afirmativa correta.','{"A": "Reconhecimento é o procedimento referente à liberação, respeitando a legislação vigente e, quando pertinente, mediante autorização judicial.", "B": "Fixação é o ato de recolher o vestígio que será submetido à análise pericial, respeitando suas características e natureza.", "C": "Armazenamento é o ato formal de transferência da posse do vestígio, que deve ser documentado com, no mínimo, informações ao número de procedimento e unidade de polícia judiciária relacionada, local de origem, nome de quem transportou o vestígio, código de rastreamento, natureza do exame, tipo do vestígio, protocolo, assinatura e identificação de quem o recebeu.", "D": "Isolamento é ato de evitar que se altere o estado das coisas, devendo isolar e preservar o ambiente imediato, mediato e relacionado aos vestígios e local de crime.", "E": "Descarte é o procedimento referente à guarda, em condições adequadas, do material a ser processado, guardado para realização de contraperícia, descartado ou transportado, com vinculação ao número do laudo correspondente."}'::jsonb,'D',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm ; https://www.planalto.gov.br/ccivil_03/leis/l9296.htm ; https://www.planalto.gov.br/ccivil_03/leis/l7960.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Sem alteração localizada.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',12,'Direito Processual Penal',null,'João Américo, 43 anos de idade, primário, é processado criminalmente pela suposta prática do delito de roubo em concurso de pessoas. Ao final da audiência de instrução e julgamento, a magistrada profere sentença condenatória e condena o réu a uma pena de reclusão de cinco anos. Inconformado com a condenação, João Américo interpõe recurso de apelação e requer a invalidação da sentença sob o fundamento de que teria havido cerceamento de defesa na instrução processual. O Ministério Público não interpõe recurso. O Tribunal de Justiça, ao julgar o recurso da defesa, nega provimento ao pedido e, por entender desproporcional a pena aplicada em decorrência da gravidade do crime praticado, aumenta a pena para seis anos de reclusão. Com base nos fatos narrados e no Código de Processo de Penal, marque a opção correta.','{"A": "O Tribunal de Justiça, com base no princípio da paridade de armas, poderia ter aumentado a pena.", "B": "O Tribunal de Justiça, com base no princípio da busca pela justiça real, poderia ter aumentado a pena.", "C": "O Tribunal de Justiça, com base no princípio do juízo natural, poderia ter aumentado a pena.", "D": "O Tribunal de Justiça, com base no princípio da vedação de bis in idem, não poderia ter aumentado a pena.", "E": "O Tribunal de Justiça, com base no princípio da vedação da reformatio in pejus, não poderia ter aumentado a pena."}'::jsonb,'E',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm ; https://www.planalto.gov.br/ccivil_03/leis/l9296.htm ; https://www.planalto.gov.br/ccivil_03/leis/l7960.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Sem alteração localizada.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',13,'Direito Processual Penal',null,'Inquérito Policial pode ser conceituado como sendo um procedimento administrativo, persecutório, instaurado e presidido por Delegado de Polícia, consistente em um conjunto de diligências com o objetivo de identificar meios de prova, produzir elementos de informação para que o titular da iniciativa da ação penal forme o seu convencimento no sentido de deflagrar a ação penal em juízo ou não e para subsidiar o magistrado em eventual pedido de medida cautelar. Tratando-se de crime de ação penal pública condicionada à representação do ofendido ou de seu representante legal, o inquérito policial não poderá ser instaurado sem representação. No tocante à representação e conforme o Código de Processo Penal, assinale a afirmativa correta.','{"A": "A representação é irretratável após o oferecimento da denúncia.", "B": "A representação é retratável até o recebimento da denúncia.", "C": "A representação é retratável até a sentença penal irrecorrível.", "D": "A representação tem a natureza de condição de punibilidade.", "E": "A representação tem a natureza de condição de recorribilidade."}'::jsonb,'A',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm ; https://www.planalto.gov.br/ccivil_03/leis/l9296.htm ; https://www.planalto.gov.br/ccivil_03/leis/l7960.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Sem alteração localizada.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',14,'Direito Processual Penal',null,'Mário Lúcio, 54 anos de idade, casado com Simone, 48 anos de idade, após acalorada discussão no almoço de domingo, por motivo de ciúmes, na residência da família, agride fisicamente a mulher causando-lhe lesão corporal leve. Após a conclusão do inquérito policial, o Ministério oferece denúncia em face de Mário Lúcio imputando-lhe a prática do crime de lesão corporal leve. A magistrada, Dra. Maria Vitória, rejeita a inicial acusatória, sob o fundamento da ausência da condição específica da ação penal representação da vítima. Com base nos fatos narrados e no entendimento dos tribunais superiores, marque a afirmativa correta.','{"A": "A magistrada agiu equivocadamente, tendo em vista tratarse de crime de ação penal privada subsidiária da pública.", "B": "A magistrada agiu corretamente, tendo em vista tratar-se de crime de ação penal pública condicionada.", "C": "A magistrada agiu equivocadamente, tendo em vista tratarse de crime de ação penal pública incondicionada.", "D": "A magistrada agiu equivocadamente, tendo em vista tratarse de crime de iniciativa privada.", "E": "A magistrada agiu corretamente, tendo em vista tratar-se de crime de ação penal pública condicionada à requisição do Ministro da Justiça."}'::jsonb,'C',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm ; https://www.planalto.gov.br/ccivil_03/leis/l9296.htm ; https://www.planalto.gov.br/ccivil_03/leis/l7960.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Sem alteração localizada.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',15,'Direito Processual Penal',null,'Pedro Henrique, 46 anos de idade, está sendo processado, criminalmente, pela suposta prática de crimes de estelionato (Pena: reclusão de 1 a 5 anos e multa). Durante a tramitação do processo, o Ministério Público requer a interceptação das ligações telefônicas de Pedro Henrique. A Dra. Cristina, magistrada titular do juízo criminal competente, por entender presentes os requisitos autorizadores, decreta a interceptação nos exatos termos do requerimento do Ministério Público. Com base nos fatos narrados e na Lei nº 9296/96, marque a afirmativa correta.','{"A": "A magistrada agiu equivocadamente, pois não é cabível interceptação das ligações telefônicas no caso de crime punido com pena de reclusão.", "B": "A magistrada agiu equivocadamente, pois não é cabível a interceptação das ligações telefônicas em virtude da pena mínima cominada ao crime ser inferior a quatro anos.", "C": "A magistrada agiu equivocadamente, pois não é cabível interceptação das ligações telefônicas na fase processual.", "D": "A magistrada agiu corretamente, pois o crime de estelionato é punido com pena de reclusão e é cabível a interceptação das ligações telefônicas na fase processual.", "E": "A magistrada agiu corretamente, pois somente é cabível interceptação das ligações telefônicas na fase processual."}'::jsonb,'D',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm ; https://www.planalto.gov.br/ccivil_03/leis/l9296.htm ; https://www.planalto.gov.br/ccivil_03/leis/l7960.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Sem alteração localizada.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',16,'Direito Processual Penal',null,'João Marcelo, 34 anos de idade, primário, está sendo processado, criminalmente, pela suposta prática do crime de homicídio culposo no trânsito. João Marcelo, conduzindo seu veículo Porsche, de modo imprudente, perdeu o controle do automóvel e atropelou Maria Helena, 59 anos de idade, que, em virtude das lesões sofridas, não resistiu e veio a óbito. O caso gerou grande repercussão social. Durante o inquérito policial e em virtude da gravidade do resultado e da repercussão social do caso, a Delegada de Polícia, Dra. Patrícia, representa pela decretação da prisão preventiva de João Marcelo. O magistrado do juízo criminal competente decreta a prisão preventiva. Com base nos fatos narrados e no Código de Processo Penal, assinale a afirmativa correta.','{"A": "É cabível, no caso, a decretação da prisão preventiva, tendo em vista a idade avançada da vítima.", "B": "É cabível, no caso, a decretação da prisão preventiva, tendo em vista a gravidade do resultado e a repercussão social do caso.", "C": "Não é cabível, no caso, a decretação da prisão preventiva, tendo em vista que a prisão preventiva somente é cabível na fase processual.", "D": "É cabível, no caso, a decretação da prisão preventiva, tendo em vista tratar-se de crime culposo com resultado morte.", "E": "Não é cabível, no caso, a decretação da prisão preventiva, tendo em vista a ausência de previsão legal do cabimento em caso de crime culposo."}'::jsonb,'E',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm ; https://www.planalto.gov.br/ccivil_03/leis/l9296.htm ; https://www.planalto.gov.br/ccivil_03/leis/l7960.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Sem alteração localizada.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',17,'Direito Processual Penal',null,'Gabriel Leite, 42 anos de idade, primário, está sendo investigado em inquérito policial pela suposta prática do crime de estupro de vulnerável. O magistrado, Dr. Guilherme, ao ter contato com a investigação criminal, por entender tratar-se de crime extremamente grave, decreta de ofício a prisão temporária de Gabriel. Com base nos fatos narrados e na Lei nº 7960/89, marque a afirmativa correta.','{"A": "É cabível a decretação da prisão temporária de ofício, desde que o crime tenha pena privativa de liberdade de reclusão máxima superior a 4 anos.", "B": "Não é cabível a decretação da prisão temporária de ofício.", "C": "Não é cabível a decretação da prisão temporária durante a investigação criminal.", "D": "É cabível a decretação da prisão temporária de ofício, tendo em vista a gravidade do crime praticado.", "E": "Não é cabível a decretação da prisão temporária na hipótese de investigado primário."}'::jsonb,'B',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm ; https://www.planalto.gov.br/ccivil_03/leis/l9296.htm ; https://www.planalto.gov.br/ccivil_03/leis/l7960.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Sem alteração localizada.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',18,'Direito Processual Penal',null,'Milena, 32 anos de idade, comete um crime que deixa vestígios (crime não transeunte). Instaurado inquérito policial para elucidar os fatos, a Delegada de Polícia identifica que os vestígios já teriam desaparecidos. Várias testemunhas foram ouvidas durante a investigação criminal. Nos termos do artigo 158 do Código de Processo Penal, quando a infração deixar vestígios, será indispensável o exame de corpo de delito, direto ou indireto, não podendo supri-lo a confissão do acusado. Ao relatar o inquérito policial, a Delegada de Polícia destaca que a prova testemunhal poderá suprir a falta do exame de corpo de delito. Com base nos fatos narrados e no Código de Processo Penal, marque a opção correta.','{"A": "Desaparecidos os vestígios, a prova testemunhal poderá suprir-lhe a falta.", "B": "A prova testemunhal não pode suprir a falta do exame de corpo delito.", "C": "A prova documental poderá suprir a falta do exame de corpo de delito.", "D": "O exame de corpo de delito, ainda que desaparecidos os vestígios, é indispensável.", "E": "A prova pericial deverá ser realizada por dois peritos oficiais, portadores de diploma de curso superior."}'::jsonb,'A',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm ; https://www.planalto.gov.br/ccivil_03/leis/l9296.htm ; https://www.planalto.gov.br/ccivil_03/leis/l7960.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Sem alteração localizada.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',19,'Direito Constitucional',null,'Marcos Paulo, 38 anos de idade, está sendo processado criminalmente pela suposta prática do crime X, cuja pena cominada é a de multa. Durante a tramitação do processo, algumas ilegalidades são cometidas pela Dra. Rosângela, magistrada titular da Vara Criminal na qual o processo tramita. Marcos Paulo encontra-se em liberdade. Com o escopo de afastar as ilegalidades e efetivar o princípio da ampla defesa, Marcos Paulo impetra a ação de Habeas Corpus. Com base nos fatos narrados, marque a afirmativa correta.','{"A": "Cabe, no caso, a impetração da ação de Habeas Corpus, tendo em vista não ser cabível a impetração da ação de mandado de segurança.", "B": "Cabe, no caso, a impetração da ação de Habeas Corpus, tendo em vista que há ameaça de lesão ao direito fundamental liberdade de locomoção.", "C": "Não cabe, no caso, a impetração da ação de Habeas Corpus, tendo em vista que, não obstante a existência de ameaça ao direito fundamental liberdade de locomoção, Marcos Paulo encontra-se em liberdade.", "D": "Cabe, no caso, a impetração da ação de Habeas Corpus, tendo em vista as ilegalidades praticadas.", "E": "Não cabe, no caso, a impetração da ação de Habeas Corpus, tendo em vista que o crime supostamente praticado não possui pena privativa de liberdade."}'::jsonb,'E',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (PEC da Segurança Pública ainda em tramitação no Senado (não promulgada); não afeta estes itens.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',20,'Direito Constitucional',null,'O Poder Legislativo está disciplinado nos artigos 44 a 76 da Constituição da República de 1988. O artigo 59 elenca os atos normativos primários. Um dos atos normativos primários é a emenda constitucional. No tocante aos legitimados para a propositura de Projeto de Emenda Constitucional, marque a afirmativa correta.','{"A": "Um terço, no mínimo, dos membros da Câmara dos Deputados ou do Senado Federal goza de legitimidade para a propositura de Projeto de Emenda Constitucional.", "B": "Metade, no mínimo, dos membros da Câmara dos Deputados ou do Senado Federal goza de legitimidade para a propositura de Projeto de Emenda Constitucional.", "C": "O Vice-Presidente da República goza de legitimidade para a propositura de Projeto de Emenda Constitucional.", "D": "Mais de um terço das Assembleias Legislativas das unidades da Federação, manifestando-se cada uma delas, pela maioria relativa de seus membros goza de legitimidade para a propositura de Projeto de Emenda Constitucional.", "E": "O Presidente do Supremo Tribunal Federal goza de legitimidade para a propositura de Projeto de Emenda Constitucional."}'::jsonb,'A',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (PEC da Segurança Pública ainda em tramitação no Senado (não promulgada); não afeta estes itens.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',21,'Direito Constitucional',null,'Flávia, 37 anos de idade, após muitos desafios e obstáculos, cola grau no Curso de Direito da Universidade Federal de Santa Catarina. Flávia tem o sonho de ser juíza. Durante vários anos, Flávia trabalha nos períodos da manhã e tarde e, na parte da noite, estuda até por volta das duas horas da madrugada. No Concurso Público para Juiz do TJSC, Flávia logra êxito em ser aprovada na primeira e na segunda etapa do certame. Ocorre que, por ter diabetes no grau leve, é desclassificada antes da realização da etapa da prova oral. A prova oral será realizada dias após a publicação da desclassificação de Flávia. Com base nos fatos narrados, assinale a opção correta.','{"A": "Impetrar a ação de Habeas Data repressivo.", "B": "Impetrar a ação de Habeas Corpus preventivo.", "C": "Impetrar a ação de Mandado de Segurança.", "D": "Impetrar a ação de Habeas Data preventivo.", "E": "Impetrar a ação de Habeas Corpus repressivo."}'::jsonb,'C',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (PEC da Segurança Pública ainda em tramitação no Senado (não promulgada); não afeta estes itens.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',22,'Direito Constitucional',null,'João Bosco, 32 anos de idade, está sendo investigado pela suposta prática dos crimes de tráfico de pessoas e lavagem de dinheiro. Durante o inquérito policial, a Delegada de Polícia, Dra. Marcela, representa para a decretação de busca e apreensão no domicílio de João Bosco. O magistrado, Dr. Américo, determina a realização da busca e apreensão. A Delegada de Polícia, às 23 horas, juntamente com outros policiais, comparece ao domicílio de João Bosco. O interfone é acionado, João Bosco atende e a Dra. Marcela se identifica e diz que possui mandado judicial para realizar a busca a apreensão. Joao Bosco, de modo educado, diz à Delegada que está assistindo a jogo de seu time de futebol, que não quer ser incomodado e desliga o interfone. Os policiais, ato contínuo, arrombam a porta da casa de João Bosco e cumprem o mandado de busca e apreensão. Diante do exposto, indique a opção correta.','{"A": "A busca e apreensão realizada é lícita, tendo em vista a presença da Delegada de Polícia ao ato.", "B": "A busca e apreensão realizada é lícita, tendo em vista a gravidade dos crimes praticados por João Bosco.", "C": "A busca e apreensão realizada é ilícita, tendo em vista que o magistrado não estava presente no momento de seu cumprimento.", "D": "A busca e apreensão realizada é ilícita, tendo em vista que foi realizada a noite e sem o consentimento de João Bosco.", "E": "A busca e apreensão realizada é lícita, tendo em vista que houve autorização do Poder Judiciário."}'::jsonb,'D',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (PEC da Segurança Pública ainda em tramitação no Senado (não promulgada); não afeta estes itens.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',23,'Direito Constitucional',null,'O artigo 136 da Constituição da República de 1988 disciplina o Estado de Defesa. Nos termos do artigo 136, é cabível o Estado de Defesa para preservar ou prontamente restabelecer, em locais restritos e determinados, a ordem pública ou a paz social ameaçadas por grave e iminente instabilidade institucional ou atingidas por calamidades de grandes proporções da natureza. No tocante ao tema Estado de Defesa, assinale a alternativa correta.','{"A": "O Congresso Nacional apreciará o decreto dentro de quinze dias, contados de seu recebimento, devendo continuar funcionando enquanto vigorar o Estado de Defesa.", "B": "Decretado o Estado de Defesa ou a sua prorrogação, o Presidente da República, dentro de vinte e quatro horas, submeterá o ato com a respectiva justificação ao Congresso Nacional, que decidirá por maioria absoluta.", "C": "Durante o Estado de Defesa é cabível a decretação da incomunicabilidade do preso.", "D": "A prisão ou detenção de qualquer pessoa não poderá ser superior a quinze dias, salvo quando autorizada pelo Poder Judiciário.", "E": "Se o Congresso Nacional estiver em recesso, será convocado, extraordinariamente, no prazo de dez dias."}'::jsonb,'B',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (PEC da Segurança Pública ainda em tramitação no Senado (não promulgada); não afeta estes itens.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',24,'Direito Constitucional',null,'Nos termos do artigo 127 da Constituição da República de 1988, o Ministério Público é instituição permanente, essencial à função jurisdicional do Estado, incumbindo-lhe a defesa da ordem jurídica, do regime democrático e dos interesses sociais e individuais indisponíveis. Nesse contexto, marque a opção que contenha os princípios institucionais do Ministério Público.','{"A": "Indivisibilidade, independência funcional e inamovibilidade.", "B": "Unidade, irredutibilidade de subsídio e independência funcional.", "C": "Independência funcional, unidade e vitaliciedade.", "D": "Vitaliciedade, unidade e inamovibilidade.", "E": "Independência funcional, unidade e indivisibilidade."}'::jsonb,'E',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (PEC da Segurança Pública ainda em tramitação no Senado (não promulgada); não afeta estes itens.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',25,'Direito Administrativo',null,'À luz do texto expresso da Lei nº 8.429/1992, após as alterações introduzidas pela Lei nº 14.230/2021, considera-se ato de improbidade administrativa aquele que:','{"A": "Seja praticado por agente público ou terceiro, ainda que ausente comprovação de elemento subjetivo específico.", "B": "É praticado com dolo, caracterizado pela vontade livre e consciente de alcançar o resultado ilícito tipificado na lei, não sendo admitida a modalidade culposa, salvo disposição legal expressa.", "C": "Resulta em dano ao erário, ainda que decorrente exclusivamente de culpa grave do agente público, desde que demonstrado nexo causal.", "D": "Viola princípios da administração pública, independentemente da demonstração de tipicidade fechada e de finalidade ilícita específica.", "E": "Decorre de erro grosseiro do agente público, quando configurada ofensa aos deveres de legalidade e eficiência."}'::jsonb,'B',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/leis/l8429.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Texto pós-Lei 14.230/2021.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',26,'Direito Administrativo',null,'Conforme a disciplina expressa da Lei nº 8.429/1992, no que se refere aos atos de improbidade administrativa que causam prejuízo ao erário, é correto afirmar que:','{"A": "Independem de tipificação expressa, desde que constatada ofensa ao patrimônio público em sentido amplo.", "B": "Admitem a responsabilização do agente público com base em presunção de dano, desde que caracterizada a ilicitude do ato administrativo.", "C": "Prescindem da demonstração de prejuízo material, bastando a potencialidade lesiva da conduta praticada.", "D": "Exigem a comprovação de dolo específico e a demonstração efetiva de perda patrimonial, desvio, apropriação, malbaratamento ou dilapidação dos bens ou haveres das entidades indicadas na lei.", "E": "Podem ser configurados por ação ou omissão culposa do agente público, quando houver violação ao dever de cuidado objetivo."}'::jsonb,'D',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/leis/l8429.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Texto pós-Lei 14.230/2021.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',27,'Direito Administrativo',null,'Nos termos da Lei nº 13.709/2018, considera-se dado pessoal sensível aquele que:','{"A": "Se refere à origem racial ou étnica, convicção religiosa, opinião política, filiação a sindicato ou a organização de caráter religioso, filosófico ou político, bem como dado referente à saúde ou à vida sexual, dado genético ou biométrico, quando vinculado a uma pessoa natural.", "B": "Identifique direta ou indiretamente pessoa natural, inclusive endereço eletrônico profissional ou dados exclusivamente cadastrais.", "C": "Esteja relacionado a informações de caráter econômico, financeiro ou patrimonial do titular, independentemente de previsão legal específica.", "D": "Seja utilizado para fins estatísticos, acadêmicos ou científicos, desde que preservada a identidade do titular.", "E": "Corresponda a qualquer informação constante de bancos de dados públicos, independentemente de seu conteúdo."}'::jsonb,'A',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',28,'Direito Administrativo',null,'Conforme texto literal da Lei nº 13.709/2018, o tratamento de dados pessoais somente poderá ser realizado nas hipóteses legais expressamente previstas, dentre as quais se inclui:','{"A": "A presunção de autorização do titular, quando o tratamento decorrer de prática reiterada do controlador.", "B": "A conveniência administrativa do controlador, desde que observados os princípios da eficiência e da economicidade.", "C": "O consentimento do titular, manifestado de forma livre, informada e inequívoca, para uma finalidade determinada.", "D": "A existência de interesse público genérico, ainda que ausente previsão legal ou regulamentar específica.", "E": "A simples disponibilidade do dado em fonte acessível ao público, independentemente da finalidade do tratamento."}'::jsonb,'C',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',29,'Direito Administrativo',null,'Consoante os termos expressos da Lei nº 12.527/2011, o acesso à informação pública pelos interessados:','{"A": "Limita-se às informações produzidas após a entrada em vigor da lei, não alcançando registros pretéritos.", "B": "Depende de motivação expressa do requerente, que deverá demonstrar interesse direto e específico na informação solicitada.", "C": "Somente será assegurado mediante prévia autorização da autoridade máxima do órgão ou entidade detentora da informação.", "D": "Poderá ser restringido por ato administrativo discricionário, sempre que envolver matéria de interesse institucional sensível.", "E": "Constitui a regra geral, sendo o sigilo exceção, devendo este ser justificado nos termos da própria lei."}'::jsonb,'E',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2011/lei/l12527.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',30,'Direito Administrativo',null,'De acordo com a Lei nº 12.527/2011, quanto à classificação das informações em razão de seu grau de sigilo, é correto afirmar que:','{"A": "A reavaliação das informações classificadas é facultativa, a critério exclusivo do órgão ou entidade responsável.", "B": "A classificação em ultrassecreta, secreta ou reservada deve observar prazos máximos de restrição de acesso expressamente fixados em lei.", "C": "As informações classificadas como ultrassecretas possuem prazo indeterminado de restrição de acesso, enquanto subsistir o interesse público.", "D": "A classificação do sigilo pode ser renovada indefinidamente, desde que mediante decisão fundamentada da autoridade competente.", "E": "As informações classificadas como reservadas não estão sujeitas a prazo máximo de restrição de acesso."}'::jsonb,'B',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2011/lei/l12527.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',31,'Direitos Humanos',null,'Nos termos expressos da Lei nº 13.060/2014, o uso de instrumentos de menor potencial ofensivo pelos agentes de segurança pública:','{"A": "Deve observar os princípios da legalidade, necessidade, razoabilidade e proporcionalidade, priorizando-se sua utilização em detrimento do uso de armas de fogo.", "B": "É facultativo, podendo o agente optar livremente pelo uso de arma de fogo sempre que julgar conveniente à atuação policial.", "C": "Somente é permitido após esgotadas todas as tentativas de negociação, ainda que inexistente risco iminente.", "D": "Restringe-se às situações de contenção de manifestações públicas e controle de distúrbios civis.", "E": "Depende de autorização expressa da autoridade superior hierárquica para cada ocorrência concreta."}'::jsonb,'A',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2014/lei/l13060.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',32,'Direitos Humanos',null,'A Declaração Universal dos Direitos Humanos, adotada pela Assembleia Geral das Nações Unidas em 10 de dezembro de 1948, tem como fundamento básico o reconhecimento de que:','{"A": "A Declaração confere aos Estados total discricionariedade para limitar direitos fundamentais.", "B": "Os direitos humanos são garantias exclusivas de Estado-soberanos em sua ação interna.", "C": "Os direitos humanos só se aplicam a indivíduos maiores de idade e com plena capacidade jurídica.", "D": "Todo ser humano nasce livre e igual em dignidade e em direitos, devendo agir com espírito de fraternidade.", "E": "Os direitos reconhecidos na Declaração podem ser retirados em casos de segurança nacional."}'::jsonb,'D',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Conteúdo atemporal conferido", "url": "https://www.un.org/pt/about-us/universal-declaration-of-human-rights"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; conteúdo atemporal conferido em 2026-10-22; ainda exige decisão individual antes de ativar (Declaração Universal de 1948.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',33,'Direitos Humanos',null,'De acordo com a Declaração Universal dos Direitos Humanos, é correto afirmar que:','{"A": "A igualdade e a dignidade humanas são conceitos reservados apenas aos direitos civis e políticos.", "B": "Todos os seres humanos podem invocar os direitos e as liberdades proclamados na presente Declaração, sem distinção alguma, nomeadamente de raça, de cor, de sexo, de língua, de religião, de opinião política ou outra, de origem nacional ou social, de fortuna, de nascimento ou de qualquer outra situação.", "C": "O direito à igualdade pode ser relativizado com base no gênero ou religião da pessoa.", "D": "A proteção igual perante a lei não engloba proteção contra discriminação.", "E": "Os direitos e liberdades só se aplicam a cidadãos de países membros das Nações Unidas."}'::jsonb,'B',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Conteúdo atemporal conferido", "url": "https://www.un.org/pt/about-us/universal-declaration-of-human-rights"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; conteúdo atemporal conferido em 2026-10-22; ainda exige decisão individual antes de ativar (Declaração Universal de 1948.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',34,'Direitos Humanos',null,'Nos termos do Decreto nº 12.341/2024, constituem princípios gerais do uso da força em segurança pública:','{"A": "A legalidade, a autoridade, a coercitividade, a autotutela e a indisponibilidade do interesse público.", "B": "A legalidade, a eficiência, a economicidade, a moralidade, a publicidade e a supremacia do interesse público.", "C": "A legalidade, a precaução, a necessidade, a proporcionalidade, a razoabilidade, a responsabilização e a não discriminação.", "D": "A legalidade, a hierarquia, a disciplina, a oportunidade e a conveniência administrativa.", "E": "A legalidade, a eficiência, a transparência, a prevenção e a repressão qualificada."}'::jsonb,'C',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Norma vigente conferida", "url": "https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/decreto/d12341.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; norma vigente conferida em 2026-10-22; ainda exige decisão individual antes de ativar (Decreto 12.341/2024 vigente; art. 2º confere com o gabarito.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',35,'Direitos Humanos',null,'Nos termos da Declaração Universal dos Direitos Humanos, no que se refere ao direito de propriedade, assinale a alternativa correta.','{"A": "O direito de propriedade depende de previsão expressa na legislação interna de cada Estado para produzir efeitos.", "B": "O direito de propriedade absoluto é assegurado somente aos nacionais do Estado em que se encontrem.", "C": "A Declaração admite a privação da propriedade sempre que houver interesse econômico homogêneo do Estado.", "D": "O direito de propriedade é reconhecido na forma individual e abstrata, sendo vedada a propriedade em comum.", "E": "Todo ser humano tem direito à propriedade, só ou em sociedade com outros, e ninguém será arbitrariamente privado de sua propriedade."}'::jsonb,'E',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Conteúdo atemporal conferido", "url": "https://www.un.org/pt/about-us/universal-declaration-of-human-rights"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; conteúdo atemporal conferido em 2026-10-22; ainda exige decisão individual antes de ativar (Declaração Universal de 1948.)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',36,'Legislação Institucional',null,'De acordo com a Lei nº 14.735, de 23 de novembro de 2023, que institui a Lei Orgânica Nacional das Polícias Civis, é correto afirmar que a Polícia Civil:','{"A": "Limita sua atuação às infrações penais de menor potencial ofensivo, nos termos definidos em regulamento.", "B": "Possui natureza temporária, sendo estruturada por cargos isolados, conforme a conveniência administrativa do ente federativo.", "C": "Exerce exclusivamente funções de polícia administrativa, vedada sua atuação na apuração de infrações penais.", "D": "Subordina-se funcionalmente ao Poder Judiciário no exercício das atividades de investigação criminal.", "E": "É órgão permanente do Estado, estruturado em carreira, destinado ao exercício das funções de polícia judiciária e à apuração das infrações penais, excetuadas as militares."}'::jsonb,'E',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14735.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',40,'Tecnologia da Informação, Segurança Cibernética e Crimes Digitais',null,'Em um cenário corporativo com sedes em cidades distintas, cada localidade mantém sua rede local conectada a um backbone centralizado por meio de enlaces gerenciados por operadoras, permitindo comunicação entre filiais. Diante desse contexto, selecione a alternativa que corretamente identifica o tipo de rede empregado.','{"A": "O ambiente configurado representa uma rede pessoal de alcance limitado.", "B": "A infraestrutura empregada caracteriza uma rede de longa distância.", "C": "O modelo descrito corresponde a uma topologia em anel.", "D": "Trata-se de uma rede local distribuída.", "E": "A arquitetura implementada é do tipo ponto a ponto exclusivo."}'::jsonb,'B',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',41,'Tecnologia da Informação, Segurança Cibernética e Crimes Digitais',null,'Um provedor de acesso à internet implementa uma solução para estender o uso de endereços IPv4 privados em sua infraestrutura, permitindo que múltiplos clientes compartilhem um mesmo endereço IP público por meio de mapeamento de portas em escala massiva. Selecione a alternativa que corretamente identifica a tecnologia empregada.','{"A": "A solução adotada corresponde ao NAT em escala de operadora.", "B": "A infraestrutura empregada baseia-se em túneis GRE ponto a ponto.", "C": "A abordagem descrita é característica do roteamento hierárquico.", "D": "Trata-se da implementação de um proxy reverso de camada 7.", "E": "O mecanismo utilizado é o IPv6 dual stack."}'::jsonb,'A',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',42,'Tecnologia da Informação, Segurança Cibernética e Crimes Digitais',null,'Em uma infraestrutura de gerenciamento de rede, um sistema centralizado coleta periodicamente informações de desempenho e status de roteadores e switches por meio de mensagens padronizadas trocadas em uma porta bem conhecida, utilizando uma arquitetura baseada em gerente e agente. Diante desse contexto, selecione a alternativa que corretamente identifica o protocolo responsável por essa funcionalidade.','{"A": "DHCP.", "B": "HTTP.", "C": "DNS.", "D": "SNMP.", "E": "FTP."}'::jsonb,'D',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',43,'Tecnologia da Informação, Segurança Cibernética e Crimes Digitais',null,'Um navegador web implementa, por padrão e sem necessidade de configuração adicional, a exclusão automática de todos os cookies, dados de sessão e histórico de navegação ao fechar cada aba individualmente, além de impedir que scripts acessem identificadores de hardware ou sensores do dispositivo para fins de identificação única. Diante desse contexto, selecione a alternativa que corretamente identifica esse navegador.','{"A": "Safari.", "B": "Google Chrome.", "C": "DuckDuckGo Browser.", "D": "Microsoft Edge.", "E": "Mozilla Firefox."}'::jsonb,'C',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',44,'Tecnologia da Informação, Segurança Cibernética e Crimes Digitais',null,'A Dark Net inclui redes ocultas como a Tor, cuja arquitetura emprega roteamento com criptografia em múltiplas camadas por meio de nós voluntários (entrada, intermediário e saída), de modo que o endereço IP do usuário permanece oculto e os serviços acessíveis nessa infraestrutura utilizam domínios alfanuméricos terminados em .onion, resolvidos apenas internamente, sem interação com o DNS convencional. Selecione a alternativa que corretamente descreve uma característica técnica exclusiva desse modelo de rede anônima.','{"A": "Distribuição de conteúdo por meio de redes de entrega de mídia com endereços IPv4 estáticos.", "B": "Acesso baseado em autenticação multifatorial com certificados digitais emitidos por autoridades centrais.", "C": "Transmissão de dados em texto claro com anonimização via NAT em roteadores de borda.", "D": "Resolução de nomes por servidores DNS públicos com suporte a registros TXT e AAAA.", "E": "Utilização de circuitos criptografados compostos por relés sequenciais e endereços de serviço derivados de chaves públicas."}'::jsonb,'E',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',45,'Tecnologia da Informação, Segurança Cibernética e Crimes Digitais',null,'Em uma cidade em expansão, a operadora de telefonia móvel instala novas unidades para estender a cobertura de voz e dados, garantindo conectividade contínua aos usuários em deslocamento. Cada unidade atua como ponto de interface entre os dispositivos móveis e a rede de transporte, operando em faixas de frequência licenciadas e gerenciando handovers entre células adjacentes. Essas unidades são denominadas','{"A": "Gateways de Borda.", "B": "Estações Rádio Base.", "C": "Controladores de Mobilidade.", "D": "Pontos de Acesso Wi-Fi.", "E": "Roteadores Celulares."}'::jsonb,'B',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',46,'Tecnologia da Informação, Segurança Cibernética e Crimes Digitais',null,'Um tipo de malware criptografa arquivos armazenados em um sistema comprometido, tornando-os inacessíveis ao usuário legítimo, e exige um pagamento em moeda digital como condição para fornecer a chave de descriptografia. Diante desse contexto, assinale a alternativa que corretamente identifica esse tipo de ameaça.','{"A": "Ransomware.", "B": "Spyware.", "C": "Adware.", "D": "Rootkit.", "E": "Worm."}'::jsonb,'A',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',47,'Tecnologia da Informação, Segurança Cibernética e Crimes Digitais',null,'Em um sistema de segurança da informação, um usuário fornece credenciais válidas — como login e senha, certificado digital ou biometria — para comprovar que é quem afirma ser, antes de obter acesso a um recurso protegido. Diante desse contexto, selecione a alternativa que corretamente identifica esse processo.','{"A": "Não repúdio.", "B": "Confidencialidade.", "C": "Autenticação.", "D": "Identificação.", "E": "Integridade."}'::jsonb,'C',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',48,'Tecnologia da Informação, Segurança Cibernética e Crimes Digitais',null,'Um software especializado é instalado em um sistema operacional com o objetivo específico de detectar, bloquear e remover programas que coletam silenciosamente informações do usuário — como hábitos de navegação, teclas digitadas ou senhas — sem seu consentimento explícito. Selecione a alternativa que corretamente identifica esse tipo de solução de segurança.','{"A": "Criptografia de disco completo.", "B": "Firewall de próxima geração.", "C": "Autenticação multifatorial.", "D": "Anti-spyware.", "E": "Sistema de prevenção de intrusão."}'::jsonb,'D',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',49,'Tecnologia da Informação, Segurança Cibernética e Crimes Digitais',null,'Após concluir o download de um pacote de atualização disponibilizado por um fabricante, um agente de polícia civil executa uma ferramenta que gera uma sequência de 64 caracteres a partir do conteúdo do arquivo baixado e a confronta com o valor divulgado pelo próprio fabricante em seu portal de suporte. A coincidência entre os dois valores atesta que o arquivo não sofreu alterações desde sua publicação. O algoritmo empregado nesse processo é:','{"A": "SSL.", "B": "RSA.", "C": "AES.", "D": "Diffie-Hellman.", "E": "SHA."}'::jsonb,'E',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',50,'Tecnologia da Informação, Segurança Cibernética e Crimes Digitais',null,'Durante a catalogação de arquivos digitais em um sistema de gestão documental, um servidor registra informações como formato do arquivo, resolução, taxa de bits, duração, codec utilizado e tamanho em bytes, com o objetivo de garantir a compatibilidade futura com softwares de visualização e reprodução. A alternativa que corretamente classifica esse tipo de metadado é:','{"A": "Técnicos.", "B": "Administrativos.", "C": "Descritivos.", "D": "De preservação.", "E": "Estruturais."}'::jsonb,'A',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',51,'Tecnologia da Informação, Segurança Cibernética e Crimes Digitais',null,'Em um procedimento de perícia digital, um arquivo é submetido a uma função que gera uma sequência alfanumérica única de 160 bits, utilizada como “impressão digital” para comprovar que o conteúdo não foi alterado desde a coleta original. A alternativa que corretamente identifica esse algoritmo é:','{"A": "Base64.", "B": "SHA-1.", "C": "RSA.", "D": "Blowfish.", "E": "HMAC."}'::jsonb,'B',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',52,'Tecnologia da Informação, Segurança Cibernética e Crimes Digitais',null,'Durante uma investigação criminal, agentes coletam publicações públicas de um perfil em uma plataforma on-line, incluindo textos, imagens e localizações geográficas associadas a postagens feitas pela suspeita ao longo de dois meses. Os dados são usados para estabelecer padrões de comportamento, deslocamentos e vínculos com outras pessoas. Essa prática corresponde ao uso de','{"A": "acesso remoto não autorizado.", "B": "interceptação telefônica.", "C": "monitoramento em tempo real.", "D": "vigilância encoberta.", "E": "inteligência de fontes abertas."}'::jsonb,'E',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',53,'Tecnologia da Informação, Segurança Cibernética e Crimes Digitais',null,'Durante uma operação policial, agentes utilizam um sistema que se conecta diretamente ao chip de memória de um smartphone, ignorando o sistema operacional, para extrair dados apagados, metadados e configurações internas que não são acessíveis por métodos convencionais. A alternativa que corretamente identifica essa abordagem forense é:','{"A": "Extração por API.", "B": "Análise lógica.", "C": "Análise física.", "D": "Backup em nuvem.", "E": "Monitoramento remoto."}'::jsonb,'C',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',54,'Tecnologia da Informação, Segurança Cibernética e Crimes Digitais',null,'Em um relatório elaborado por uma unidade de análise, um agente cruza registros de ligações telefônicas, dados de localização de dispositivos móveis e históricos de antecedentes criminais, identificando padrões que permitem antecipar a ocorrência de novos delitos em determinada região. A alternativa que corretamente descreve o produto final desse processo analítico é:','{"A": "Metadado.", "B": "Dado.", "C": "Informação.", "D": "Inteligência.", "E": "Conhecimento."}'::jsonb,'D',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',55,'Tecnologia da Informação, Segurança Cibernética e Crimes Digitais',null,'Em um modelo de rede neural artificial, além dos pesos das conexões entre neurônios, cada unidade de processamento recebe um valor fixo adicionado à soma ponderada de suas entradas, cuja função é ajustar o limiar de ativação do neurônio, permitindo maior flexibilidade na modelagem de padrões complexos. A alternativa que corretamente identifica esse componente é:','{"A": "Gradientes descendentes.", "B": "Viéses.", "C": "Funções de perda.", "D": "Taxas de aprendizado.", "E": "Camadas de pooling."}'::jsonb,'B',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',56,'Tecnologia da Informação, Segurança Cibernética e Crimes Digitais',null,'Em um sistema descentralizado baseado em blockchain, um usuário recebe ativos digitais por meio de um identificador gerado a partir de sua chave privada por meio de uma função matemática unidirecional. Esse identificador pode ser compartilhado livremente para recebimento de recursos, mas, por si só, não permite movimentar os ativos associados. É correto afirmar que esse identificador corresponde a:','{"A": "Chave pública.", "B": "Hash de transação.", "C": "Endereço IP.", "D": "Código QR.", "E": "Assinatura digital."}'::jsonb,'A',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',57,'Tecnologia da Informação, Segurança Cibernética e Crimes Digitais',null,'Em uma investigação envolvendo transações de criptoativos, agentes observam que a rede em questão exige dos participantes a resolução de problemas computacionais intensivos, cuja solução é verificada de forma eficiente por todos os nós, garantindo a imutabilidade do livro-razão e permitindo o rastreamento de todas as operações em um registro público e sequencial. Esse mecanismo de consenso é denominado:','{"A": "Sistema de validação por múltiplos signatários.", "B": "Algoritmo Prova de Participação.", "C": "Protocolo de consenso por votação federada.", "D": "Algoritmo Prova de Trabalho.", "E": "Mecanismo de consenso baseado em autoridade."}'::jsonb,'D',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',58,'Tecnologia da Informação, Segurança Cibernética e Crimes Digitais',null,'Um agente instala um programa malicioso em um sistema de gestão financeira que, sem qualquer intervenção ou participação das vítimas — e sem que estas tenham sido induzidas a erro, tenham inserido dados ou autorizado transações —, subtrai recursos diretamente por meio de comandos automatizados. Esse fato configura tipicamente:','{"A": "Uso não autorizado de software de monitoramento.", "B": "Estelionato mediante uso de dispositivo eletrônico.", "C": "Furto qualificado por meio informático.", "D": "Interferência maliciosa em equipamento de segurança de rede.", "E": "Acesso indevido a dispositivo móvel."}'::jsonb,'C',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',59,'Tecnologia da Informação, Segurança Cibernética e Crimes Digitais',null,'Um provedor de conexão à Internet, alegando custos operacionais elevados, contrata uma empresa terceirizada para armazenar e gerenciar os registros de conexão de seus usuários, transferindo formalmente a responsabilidade legal pela integridade e disponibilidade desses dados para essa contratada. O trecho do Marco Civil da Internet que proíbe essa conduta é:','{"A": "A autoridade policial pode requisitar dados cadastrais sem autorização judicial em casos de urgência.", "B": "Os registros de acesso devem ser mantidos pelo provedor de aplicações por período mínimo de seis meses.", "C": "O provedor de conexão deve garantir a confidencialidade dos dados pessoais dos usuários.", "D": "A neutralidade de rede deve ser observada em toda a infraestrutura de telecomunicações.", "E": "A responsabilidade pela manutenção dos registros de conexão não poderá ser transferida a terceiros."}'::jsonb,'E',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',64,'Contabilidade',null,'A Lei nº 10.406/2002 apresenta situações em que pode haver a desconsideração da personalidade jurídica para que os efeitos de certas obrigações sejam estendidos aos bens particulares de administradores ou de sócios da pessoa jurídica beneficiados direta ou indiretamente pelo abuso da personalidade jurídica. Assinale a alternativa que expõe essas situações.','{"A": "Abuso da personalidade jurídica, caracterizado pela declaração de insolvência/falência ou por prejuízos sucessivos aos sócios.", "B": "Abuso da personalidade jurídica, caracterizado pelo desvio de finalidade ou pela declaração de insolvência/falência.", "C": "Abuso da personalidade jurídica, caracterizado pela expansão ou a alteração da finalidade original da atividade econômica específica da pessoa jurídica.", "D": "Abuso da personalidade jurídica, caracterizado pelo desvio de finalidade ou pela confusão patrimonial.", "E": "Abuso da personalidade jurídica, caracterizado pelo cancelamento da inscrição da pessoa jurídica e a transferência de ativos ou de passivos sem efetivas contraprestações."}'::jsonb,'D',false,false,'2026-10-22T12:00:00Z'::timestamptz,'[{"title": "Sem alteração legislativa localizada", "url": "https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm"}]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno; sem alteração legislativa localizada em 2026-10-22; ainda exige decisão individual antes de ativar (Art. 50 CC (Lei 13.874/2019).)'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',66,'Língua Portuguesa',null,'Pelas especificidades inerentes ao texto em análise, depreende-se que se trata de:','{"A": "uma narrativa de memória, uma vez que o texto se estrutura a partir de lembranças pessoais do autor, recuperando experiências vividas no passado para refletir sobre o sofrimento e a felicidade.", "B": "uma crônica, uma vez que o autor discute temas universais da experiência humana a partir de opiniões pessoais e reflexões existenciais.", "C": "um artigo de opinião, visto que o autor defende um ponto de vista sobre o sofrimento humano por meio de argumentação lógica e linguagem persuasiva.", "D": "um ensaio filosófico, já que o texto se dedica exclusivamente à problematização conceitual da felicidade e da dor, sem recorrer a estratégias injuntivas.", "E": "um conto, pois apresenta um único conflito, com poucos personagens; espaço e tempo limitados, estruturados em apresentação, complicação, clímax e desfecho."}'::jsonb,'B',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',67,'Língua Portuguesa',null,'A estratégia usada pelo autor, para dar consistência argumentativa ao seu texto, foi por meio de:','{"A": "um trocadilho.", "B": "uma fábula.", "C": "um apólogo.", "D": "uma alegoria.", "E": "uma epifania."}'::jsonb,'D',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',68,'Língua Portuguesa',null,'“[...] a receita para não sofrer é muito simples: basta ‘matar’ o amor.” O vocábulo “matar”, na passagem anterior, pode ser substituído por outra palavra, sem prejuízo de sentido ao contexto inicial, em:','{"A": "suprimir.", "B": "dirimir.", "C": "achacar.", "D": "acoimar.", "E": "estorvar."}'::jsonb,'A',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',69,'Língua Portuguesa',null,'“Acho que sabedoria é saber sofrer pelas razões certas.” A partir da subjetividade contida no trecho do gênero em voga, é possível caracterizar a estrutura sintática demarcada como uma modalização discursiva do tipo:','{"A": "afetiva.", "B": "lógica.", "C": "epistêmica.", "D": "volitiva.", "E": "deôntica."}'::jsonb,'C',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',70,'Língua Portuguesa',null,'O uso do sinal indicativo de crase, assim como no excerto que segue, está correto em: “Toda experiência de amor traz, encolhida no seu ventre, à espera, a possibilidade de sofrer.”','{"A": "Referi-me à uma moça.", "B": "Referi-me à ela.", "C": "Referi-me à ele.", "D": "Referi-me àquele rapaz.", "E": "Referi à essa moça."}'::jsonb,'D',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',71,'Língua Portuguesa',null,'Os grupos da sintaxe se dividem em essenciais, integrantes e acessórias. Assim sendo, aponte, dentre os itens seguintes, aquele que pertença ao mesmo grupo sintático do termo destacado na passagem: “[...] se o fogo consome as florestas [...]”','{"A": "“[...] o seu pior inimigo receberia em dobro!”", "B": "“[...] se uma desgraça cai sobre o povo e a alma não fica triste.”", "C": "“[...] significa que estamos em contato com a realidade.”", "D": "“A felicidade pode ser destruída por uma doença que mora em nossos olhos.”", "E": "“[...] o felizardo começa a imaginar tudo o que poderia pedir.”"}'::jsonb,'C',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',72,'Língua Portuguesa',null,'“Mas que enorme seria a perda se isso acontecesse!” O verbo realçado indica um fato que:','{"A": "ocorria de forma contínua, habitual, mas foi interrompido.", "B": "ocorrerá em um momento posterior ao da fala.", "C": "ocorreu antes de outro, também no passado.", "D": "aconteceu antes do momento em que falamos.", "E": "poderia ter acontecido posteriormente a uma situação passada."}'::jsonb,'E',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',73,'Língua Portuguesa',null,'Assim como a estrutura sintática iniciada pelo verbo haver no período a seguir, a concordância verbal também se faz corretamente, conforme a norma-padrão, em: “[...] há outros sofrimentos [...].”','{"A": "“[...] hão de existir outros sentimentos [...]”", "B": "“[...] hão outros sofrimentos [...]”", "C": "“[...] existe outros sofrimentos[...]”", "D": "“[...] pode existir outros sofrimentos [...]”", "E": "“[...] devem haver outros sofrimentos [...]”"}'::jsonb,'A',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',74,'Língua Portuguesa',null,'Na passagem em evidência, o trecho realçado desempenha função de aposto: “Tão logo percebe que aquilo era mesmo possível, o felizardo começa a imaginar tudo o que poderia pedir: a juventude, uma beleza física irresistível, palácios deslumbrantes nos quatro cantos do mundo, serviçais, as mais belas mulheres, os melhores vinhos, as comidas mais saborosas, os amigos fiéis.”','{"A": "resumitivo.", "B": "enumerativo.", "C": "especificativo.", "D": "recapitulativo.", "E": "distributivo."}'::jsonb,'B',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',75,'Língua Portuguesa',null,'Escreve-se corretamente com /x/, bem como a palavra demarcada em “Toda experiência de amor [...]”, o vocábulo contextualizado na alternativa:','{"A": "Alcaxofra é uma flor nativa do Mediterrâneo.", "B": "Precisamos extender o prazo.", "C": "Ele é experto na área jurídica.", "D": "Passamos as férias em um xalé.", "E": "O xucrute é feito de repolho fermentado."}'::jsonb,'C',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',76,'Língua Portuguesa',null,'Atente-se ao excerto que segue para assinalar a alternativa correta em se tratando das regras de colocação pronominal. “Um homem encontra uma garrafa que estava enterrada e, ao abri-la, surpreende-se¹ com a saída de um gênio, que se² coloca ao seu serviço. O gênio diz ao homem que pode transformar em realidade todos os seus sonhos.”','{"A": "Em 2, há uma infração na ocorrência da próclise, em decorrência da hierarquia enclítica.", "B": "Em 1, ocorre ênclise em decorrência da preposição subsequente.", "C": "Em 2, a próclise ocorre em decorrência da vírgula antecedente.", "D": "Em 2, a próclise ocorre em decorrência do pronome antecedente.", "E": "Em 1, há uma infração na ocorrência da ênclise, em decorrência da hierarquia proclítica."}'::jsonb,'D',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',77,'Língua Portuguesa',null,'Analise os períodos I e II, para demarcar o item correto, em se tratando do uso ou da ausência da vírgula em relação aos elementos conectores destacados. “Um homem encontra uma garrafa que estava enterrada [...]” II. “[...] e, ao abri-la, surpreende-se com a saída de um gênio, que se coloca ao seu serviço.” I.','{"A": "Em I e em II, da ausência para o acréscimo da vírgula, há a modificação tanto do aspecto semântico dos períodos, como do aspecto sintático das sentenças.", "B": "Em I e em II, há adição de informação em relação aos antecedentes.", "C": "Em I e em II, há limitação de informação em relação aos antecedentes.", "D": "Em I, a ausência da vírgula adiciona uma informação em relação ao antecedente; enquanto em II, o uso da vírgula limita a informação.", "E": "Em I, a ausência da vírgula limita a informação; enquanto em II, o uso da vírgula adiciona uma informação em relação ao antecedente."}'::jsonb,'E',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',78,'Língua Portuguesa',null,'“[...] o corpo e a alma sentem a tristeza das perdas” O trecho demarcado anteriormente desempenha a mesma função sintática do termo destacado no item:','{"A": "Beijei-lhe as mãos em sinal de perdão.", "B": "Ninguém lhe era contrário.", "C": "Deixei-lhe resolver o problema.", "D": "Não lhe deu a mínima atenção.", "E": "Cortei-lhe as atitudes inconvenientes."}'::jsonb,'B',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',79,'Língua Portuguesa',null,'Desempenha a mesma função sintática do trecho realçado a seguir o vocábulo ressaltado em: “Toda experiência de amor traz, encolhida no seu ventre, à espera, a possibilidade de sofrer.”','{"A": "“[...] dirige-se ao gênio para fazer seu único pedido.”", "B": "“[...] é porque algo está errado com a gente.”", "C": "“[...] tudo aquilo que o homem pedisse para si [...]”", "D": "“[...] como que por encanto, a face do sortudo muda de expressão.”", "E": "“[...] e, ao abri-la, surpreende-se com a saída de um gênio.”"}'::jsonb,'E',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',80,'Língua Portuguesa',null,'“O gênio diz ao homem que pode transformar em realidade todos os seus sonhos. Sobre a regência do verbo dizer, no período em evidência, é verdadeiro afirmar que','{"A": "é bitransitiva, em que ao homem é seu objeto indireto, e a oração iniciada pela conector “que”; seu objeto direto.", "B": "é transitiva indireta, em que o termo homem é seu objeto indireto.", "C": "é transitiva direta, em que o termo sonhos é o núcleo de seu objeto direto.", "D": "é intransitiva, pois, nesse contexto, o verbo dizer apresenta autossuficiência sintático-semântica.", "E": "é transitiva indireta, em que o trecho preposicionado em realidade todos os seus sonhos é seu objeto indireto."}'::jsonb,'A',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',81,'Língua Portuguesa',null,'Atente-se aos períodos I e II a seguir para assinalar a alternativa correta. I. “Acho que sabedoria é saber sofrer pelas razões certas.” II. “Porque é o sofrimento que nos faz pensar.”','{"A": "Em I, o que se trata de conjunção subordinativa; em II, de preposição.", "B": "Em I e em II, o que se trata de pronome relativo.", "C": "Em I e em II, o que se trata de conjunção integrante.", "D": "Em I, o que se trata de conjunção integrante; em II, de pronome relativo.", "E": "Em I, o que se trata de pronome relativo; em II, de conjunção integrante."}'::jsonb,'D',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',82,'Língua Portuguesa',null,'A coesão textual, a partir da progressão temática proporcionada pela conjunção demarcada a seguir, é do tipo: “Logo, como que por encanto, a face do sortudo muda de expressão [...]”','{"A": "referencial por forma lexical.", "B": "referencial elíptica.", "C": "sequencial frástica.", "D": "sequencial parafrástica.", "E": "referencial por pró-forma."}'::jsonb,'C',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',83,'Língua Portuguesa',null,'Analise a relação coesiva existente entre os trechos ressaltados respectivamente, no período seguinte, para marcar o item correto. “Assim, a receita para não sofrer é muito simples: basta ‘matar’ o amor.”','{"A": "Há uma dêixis, pois há uma referência à situação de enunciação, e não a um termo do próprio texto.", "B": "Há uma catáfora, pois a explicação do referente surge depois do termo que o anuncia.", "C": "Há uma catáfora, pois a explicação do referente surge antes do termo que o anuncia.", "D": "Há uma anáfora, pois a explicação do referente surge antes do termo que o anuncia.", "E": "Há uma anáfora, pois a explicação do referente surge depois do termo que o anuncia."}'::jsonb,'B',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',84,'Língua Portuguesa',null,'As categorias sintáticas são as funções que as palavras ou os grupos de palavras desempenham dentro de uma frase ou oração, definindo a relação entre os termos para a construção dos sentidos. A partir dessa definição, aponte a alternativa a seguir em que a função sintática ressaltada esteja corretamente descrita entre parênteses.','{"A": "“A felicidade pode ser destruída por uma doença que mora em nossos olhos.” (complemento nominal)", "B": "“[...] se uma desgraça cai sobre o povo e a alma não fica triste [...]” (adjunto adverbial)", "C": "“[...] enorme seria a perda se isso acontecesse [...]” (predicativo do sujeito)", "D": "“O pensamento, assim, filho da dor, está a serviço da alegria.” (vocativo)", "E": "“Quem não sofre, quando há razões para isso, está doente.” (objeto direto)"}'::jsonb,'E',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',85,'Língua Portuguesa',null,'O vocábulo destacado em “Quem é feliz e nunca sofre padece de uma grave enfermidade” apresenta a mesma função sintática da oração subordinada realçada na alternativa:','{"A": "“[...] o felizardo começa a imaginar tudo o que poderia pedir.”", "B": "“[...] pois ele sabe que tem nas mãos a chave para a felicidade.”", "C": "“[...] Tão logo percebe que aquilo era mesmo possível [...]”", "D": "“[...] dirige-se ao gênio para fazer seu único pedido.”", "E": "“[...] ‘quero que me fure um olho’.”"}'::jsonb,'A',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',86,'Raciocínio Lógico-Matemático',null,'Durante uma ronda policial, a probabilidade de encontrar um veículo suspeito é de 0,15. Considerando que os agentes realizam três rondas independentes em áreas distintas, temos que a probabilidade de não localizar nenhum veículo suspeito em nenhuma das três rondas é aproximadamente:','{"A": "72,2%.", "B": "64,8%.", "C": "84,5%.", "D": "56,9%.", "E": "61,4%."}'::jsonb,'E',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',87,'Raciocínio Lógico-Matemático',null,'De um grupo de 8 peritos forenses, 3 serão escolhidos para compor uma equipe. Dentro dessa equipe, um será o Coordenador, outro será o Relator e o terceiro será o Auxiliar. O total de maneiras distintas que essa equipe pode ser formada é igual a:','{"A": "428.", "B": "336.", "C": "360.", "D": "240.", "E": "464."}'::jsonb,'B',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',88,'Raciocínio Lógico-Matemático',null,'A performance de um agente da Polícia Civil é avaliada com base em três critérios: casos solucionados (peso 4), relatórios de campo (peso 3) e engajamento comunitário (peso 1). Em uma avaliação, um agente obteve as seguintes notas: 8,5 em casos solucionados; 9,0 em relatórios de campo e 7,0 em engajamento comunitário. A nota média ponderada da performance deste agente é igual a:','{"A": "8,5.", "B": "8,0.", "C": "8,2.", "D": "8,8.", "E": "7,8."}'::jsonb,'A',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',89,'Raciocínio Lógico-Matemático',null,'O orçamento destinado à tecnologia em uma delegacia da Polícia Civil aumenta anualmente em progressão geométrica. Temos que no terceiro ano o orçamento foi de R$ 80.000,00 e no quinto ano foi de R$ 320.000,00. O valor, em reais, do orçamento no primeiro ano foi igual a:','{"A": "R$ 30.000,00.", "B": "R$ 24.000,00.", "C": "R$ 28.000,00.", "D": "R$ 15.000,00.", "E": "R$ 20.000,00."}'::jsonb,'E',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',90,'Raciocínio Lógico-Matemático',null,'Cinco delegacias foram avaliadas quanto à eficiência de resolução de crimes, apresentando os seguintes índices: Delegacia A: 0,85; Delegacia B: ; Delegacia C: 0,805; e a Delegacia E: Delegacia D: Escrevendo todos os índices na forma decimal, temos que a delegacia com o menor índice de eficiência é a:','{"A": "E.", "B": "A.", "C": "B.", "D": "C.", "E": "D."}'::jsonb,'C',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',91,'Raciocínio Lógico-Matemático',null,'Seja P(x) o predicado “x é um suspeito” e Q(x) o predicado “x tem antecedentes criminais”. A representação lógica da afirmação “Existe um suspeito que não tem antecedentes criminais” é:','{"A": "∀x (Q(x) → P(x))", "B": "∀x (P(x) → Q(x))", "C": "∃x (P(x) ^ ~Q(x))", "D": "∃x (P(x) ^ Q(x))", "E": "~∃x (P(x) ^ Q(x))"}'::jsonb,'C',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',92,'Raciocínio Lógico-Matemático',null,'Um investigador da Polícia Civil está analisando uma série de códigos numéricos encontrados em anotações de um suspeito. Ao observar a sequência: 9, 11, 15, 23, X, 71; ele descobriu que existe um padrão lógico. O valor de X que completa logicamente essa sequência é igual a:','{"A": "49.", "B": "33.", "C": "35.", "D": "39.", "E": "45."}'::jsonb,'D',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',93,'Raciocínio Lógico-Matemático',null,'Um agente da Polícia Civil está analisando a planta de um edifício onde ocorreu um crime. O crime ocorreu em uma sala retangular com um perímetro de 30 metros e em que uma das dimensões é 3 metros maior que a outra. A área dessa sala retangular, em metros quadrados, é igual a:','{"A": "64.", "B": "48.", "C": "72.", "D": "54.", "E": "60."}'::jsonb,'D',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',94,'Raciocínio Lógico-Matemático',null,'O total de anagramas que a palavra AGENTE possui, de modo que não se tenha as duas vogais iguais juntas, é igual a:','{"A": "240.", "B": "120.", "C": "280.", "D": "320.", "E": "300."}'::jsonb,'A',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',95,'Raciocínio Lógico-Matemático',null,'Alexandre, Bruno, Cleber, Douglas e Edson são suspeitos e estão sendo interrogados sobre um crime. Sabe-se que apenas um deles é o culpado, e apenas o culpado mente; os outros quatro falam a verdade. As declarações de cada um foram: Alexandre: “Bruno é o culpado.” Bruno: “Eu não sou o culpado.” Cleber: “Alexandre mente.” Douglas: “Cleber não é o culpado.” Edson: “Douglas fala a verdade.” A partir dessas informações, temos que o culpado é:','{"A": "Edson.", "B": "Bruno.", "C": "Cleber.", "D": "Douglas.", "E": "Alexandre."}'::jsonb,'E',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',96,'Raciocínio Lógico-Matemático',null,'Em um pátio da Polícia Civil, estão armazenados 16 veículos apreendidos, dos quais 10 foram identificados como furtados e 6 como adulterados. Se um perito selecionar aleatoriamente dois desses veículos, um após o outro e sem reposição, temos que a probabilidade de que ambos os veículos selecionados sejam furtados é igual a:','{"A": "32,5%.", "B": "37,5%.", "C": "42,5%.", "D": "22,5%.", "E": "27,5%."}'::jsonb,'B',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',97,'Raciocínio Lógico-Matemático',null,'Um setor de análise de evidências digitais da Polícia Civil possui 4 analistas que possuem a mesma produtividade, que ao trabalharem 6 horas por dia, conseguiram processar 120 gigabytes (GB) de dados em 10 dias. Sabe-se que, em uma nova demanda, 3 desses analistas foram designados para processar 270 gigabytes (GB) de dados e que trabalharão 9 horas por dia. O total de dias em que essa nova demanda será concluída é igual a:','{"A": "20.", "B": "16.", "C": "18.", "D": "24.", "E": "15."}'::jsonb,'A',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',98,'Raciocínio Lógico-Matemático',null,'A Polícia Civil adquiriu uma nova viatura pelo valor de R$ 180.000,00. Sabe-se que esse tipo de veículo sofre uma depreciação de 15% ao ano sobre o valor do ano anterior. O valor, em reais, dessa viatura após 2 anos de uso é igual a:','{"A": "R$ 138.020,00.", "B": "R$ 130.050,00.", "C": "R$ 122.800,00.", "D": "R$ 156.000,00.", "E": "R$ 140.600,00."}'::jsonb,'B',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',99,'Raciocínio Lógico-Matemático',null,'Um estudo da Polícia Civil sobre 100 crimes violentos recentes revelou que 47 ocorreram com uso de arma de fogo (AF), 30 ocorreram durante o período noturno (PN), 20 ocorreram em áreas rurais (AR), 10 ocorreram com AF e PN, 8 ocorreram com AF e AR, 5 ocorreram com PN e AR, 3 ocorreram com AF, PN e AR. O total de crimes que ocorreram com apenas uma dessas três características (apenas AF, apenas PN ou apenas AR) é igual a:','{"A": "72.", "B": "64.", "C": "55.", "D": "60.", "E": "48."}'::jsonb,'D',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno'),
('IDECAN','PC SC - Agente de Polícia Civil 2026','Agente de Polícia Civil',2026,null,'Tipo B',100,'Raciocínio Lógico-Matemático',null,'Considere a proposição condicional: “Se o suspeito for encontrado no local do crime (P), então ele será interrogado (Q).” A negação dessa proposição é dada por:','{"A": "O suspeito não é encontrado no local do crime e não é interrogado.", "B": "O suspeito não é encontrado no local do crime ou ele é interrogado.", "C": "O suspeito é encontrado no local do crime e ele não é interrogado.", "D": "Se o suspeito for interrogado, então ele foi encontrado no local do crime.", "E": "Se o suspeito não for encontrado no local do crime, então ele não será interrogado."}'::jsonb,'C',false,false,null,'[]'::jsonb,'SC','Polícia Civil','https://arquivos.qconcursos.com/prova/arquivo_prova/148842/idecan-2026-pc-sc-agente-de-policia-civil-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/148842/idecan-2026-pc-sc-agente-de-policia-civil-gabarito.pdf','disciplina atribuída pela ordem do caderno')
